    /def _eval_subs/,/return self.func.*base.*base/ {
        s/cond = self.condition\.subs(old, new)/# Added explicit variable scope checking
        # Ensure bound variables are not accidentally replaced
        if old == self.sym:
            # Special handling for bound variable substitution
            cond = self.condition
        else:
            # Normal substitution for free variables
            cond = self.condition.subs(old, new)
        base = self.base_set.subs(old, new)/
    }
}' sympy/sets/conditionset.py

